import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Privacy Choices","description":"","frontmatter":{},"headers":[],"relativePath":"guide/privacy-choices.md","filePath":"guide/privacy-choices.md","lastUpdated":1785319710000}`),a={name:`guide/privacy-choices.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="privacy-choices" tabindex="-1">Privacy Choices <a class="header-anchor" href="#privacy-choices" aria-label="Permalink to “Privacy Choices”">​</a></h1><p>Sudoku is an offline-first app with minimal data practices. This page explains your privacy options and how to control your data.</p><h2 id="your-data-stays-on-your-device-by-default" tabindex="-1">Your Data Stays on Your Device (By Default) <a class="header-anchor" href="#your-data-stays-on-your-device-by-default" aria-label="Permalink to “Your Data Stays on Your Device (By Default)”">​</a></h2><ul><li>All game data — settings, game state, pencil notes, and statistics — is stored locally on your device by default.</li><li>Core gameplay requires zero network access.</li><li>There are no ads, no analytics, and no tracking.</li></ul><h2 id="optional-cloud-features" tabindex="-1">Optional Cloud Features <a class="header-anchor" href="#optional-cloud-features" aria-label="Permalink to “Optional Cloud Features”">​</a></h2><h3 id="icloud-sync" tabindex="-1">iCloud Sync <a class="header-anchor" href="#icloud-sync" aria-label="Permalink to “iCloud Sync”">​</a></h3><p>If you choose to enable iCloud sync:</p><ul><li>Data is synced to <strong>your personal iCloud account</strong> only — not to any server we control.</li><li>Apple&#39;s CloudKit handles encryption in transit and at rest.</li><li>You can disable this at any time: Settings → [Your Name] → iCloud → Apps Using iCloud → toggle Sudoku off.</li></ul><h3 id="game-center" tabindex="-1">Game Center <a class="header-anchor" href="#game-center" aria-label="Permalink to “Game Center”">​</a></h3><p>If you choose to use Game Center:</p><ul><li>Leaderboard scores may appear publicly under your Game Center display name.</li><li>Achievement progress is recorded by Game Center.</li><li>You can disable this by signing out of Game Center in Settings.</li></ul><h2 id="the-only-non-cloud-network-feature-more-apps" tabindex="-1">The Only Non-Cloud Network Feature: &quot;More Apps&quot; <a class="header-anchor" href="#the-only-non-cloud-network-feature-more-apps" aria-label="Permalink to “The Only Non-Cloud Network Feature: &quot;More Apps&quot;”">​</a></h2><p>The only other network access is the optional <strong>&quot;More Apps&quot;</strong> section in Settings, which fetches a list of sibling apps. This feature:</p><ul><li>Sends no personal data — it only retrieves a list of app names and links.</li><li>Can be ignored entirely with no impact on gameplay.</li><li>Does not track you or store any identifiers.</li></ul><h2 id="clearing-your-data" tabindex="-1">Clearing Your Data <a class="header-anchor" href="#clearing-your-data" aria-label="Permalink to “Clearing Your Data”">​</a></h2><p>To remove all app data from your device:</p><ul><li><strong>iPhone/iPad</strong>: Delete and reinstall the app</li><li><strong>Mac</strong>: Quit Sudoku, then remove the container:</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.sudoku</span></span></code></pre></div><p>To also clear iCloud-synced data:</p><ol><li>Go to <strong>Settings → [Your Name] → iCloud → Manage Account Storage</strong></li><li>Find Sudoku in the app list</li><li>Tap <strong>Delete Data</strong></li></ol><p>This will permanently delete all settings, statistics, game saves, and daily challenge progress from iCloud.</p><h2 id="no-tracking-no-ads" tabindex="-1">No Tracking, No Ads <a class="header-anchor" href="#no-tracking-no-ads" aria-label="Permalink to “No Tracking, No Ads”">​</a></h2><p>Sudoku contains no advertising, no analytics, no tracking pixels, and no third-party data-sharing integrations. The app does not require network access for gameplay.</p><h2 id="privacy-requests-summary" tabindex="-1">Privacy Requests Summary <a class="header-anchor" href="#privacy-requests-summary" aria-label="Permalink to “Privacy Requests Summary”">​</a></h2><table tabindex="0"><thead><tr><th>Request</th><th>Required?</th><th>What it does</th></tr></thead><tbody><tr><td>Local storage</td><td>Yes (automatic)</td><td>Stores game data on device</td></tr><tr><td>iCloud sync</td><td>Optional</td><td>Syncs data across your devices via CloudKit</td></tr><tr><td>Game Center</td><td>Optional</td><td>Leaderboards &amp; achievements</td></tr><tr><td>Network (&quot;More Apps&quot;)</td><td>Optional</td><td>Fetches sibling app list</td></tr></tbody></table><p>Since no personal data is collected or transmitted to servers we control, there is no central database to access, delete, or port. All data is either local or managed by Apple&#39;s services (iCloud/Game Center).</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to “Contact”">​</a></h2><p>If you have questions about this process, open an issue at <code>https://github.com/sudoku-pro/sudoku-site/issues</code> or email <a href="mailto:sudoku@w3cub.com" target="_blank" rel="noreferrer">sudoku@w3cub.com</a>.</p>`,28)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};